<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ChatDotRound, Check, Download, Plus, Refresh, Search, Upload } from '@element-plus/icons-vue'
import { ElMessage, ElMessageBox } from 'element-plus'

const props=defineProps<{token:string;permissions:string[]}>()
const route=useRoute(),router=useRouter()
const loading=ref(false),error=ref(''),rows=ref<any[]>([]),active=ref<any>(null),products=ref<any[]>([]),scenes=ref<any[]>([]),templates=ref<any[]>([]),rules=ref<any[]>([]),bomVersions=ref<any[]>([]),dashboard=ref<any>(null)
const question=ref(''),answer=ref<any>(null),rawRequirement=ref(String(route.query.requirement||'')),parsed=ref<any>(null),step=ref(0),recommended=ref<any>(null),createdProjectId=ref<number|null>(null)
const bom=ref<any[]>([]),validation=ref<any>(null),selectedTemplate=ref<number|null>(null),preview=ref<any>(null),lastExport=ref<any>(null),exportTab=ref('data'),projectTab=ref('overview')
const candidateSearch=ref(''),candidateCategory=ref('全部'),leftCollapsed=ref(false),rightCollapsed=ref(false),bomDrawer=ref(false),bomDraft=reactive<any>({}),bomEditIndex=ref(-1),overrideDialog=ref(false),overrideReason=ref('')
const mappingTemplate=ref<any>(null),templateAnalysis=ref<any>(null),selectedCell=ref(''),mappingField=ref('project_name'),mappingStep=ref(0),sheetZoom=ref(100)
const templateMapping=reactive({sheetName:'',placeholderMappings:{} as Record<string,string>,bomTemplateRow:1,bomColumnMappings:{} as Record<string,string>})
const projectForm=reactive({name:'',customer:'',region:'',scene_id:null as number|null,notes:''})
const ruleForm=reactive({code:'',name:'',rule_type:'REQUIRE',condition:{sceneId:null as number|null},action:{productId:null as number|null,quantity:1},enabled:true})
const documentDialog=ref(false),pendingDocument=ref<File|null>(null),editingDocument=ref<any>(null),documentSearch=ref(''),documentCategory=ref('全部'),documentType=ref('全部'),documentPreview=ref(false),previewDocument=ref<any>(null),documentPreviewUrl=ref(''),documentPreviewLoading=ref(false)
const documentForm=reactive({category:'产品资料',version:'V1.0',description:'',applicable_models:'',applicable_versions:'',center_type:'',center_id:null as number|null,knowledge_enabled:false})
const statusLabels:Record<string,string>={DRAFT:'需求整理',CONFIGURING:'配单中',CONFIRMED:'已确认',EXPORTED:'已导出',ARCHIVED:'已归档'}
const ruleTypeLabels:Record<string,string>={REQUIRE:'必选规则',QUANTITY:'数量规则',CONDITION:'条件规则',COMPATIBILITY:'兼容规则',EXCLUDE:'互斥规则',RECOMMEND:'推荐规则'}
const validationLabels:Record<string,string>={PASS:'配置通过',WARNING:'存在提醒',ERROR:'存在错误'}
const requirementLabels:Record<string,string>={scene:'场景',upstreamKm:'上游覆盖',downstreamKm:'下游覆盖',ptzCount:'视频设备',ais:'AIS融合',ocr:'船名OCR',yaw:'偏航预警',continuousOperation:'运行要求'}
const documentStatusLabels:Record<string,string>={DRAFT:'草稿',PUBLISHED:'已发布',CURRENT:'当前有效',HISTORICAL:'历史版本',OBSOLETE:'已废止',NOT_SYNCED:'未同步',PROCESSING:'同步中',SYNCED:'已同步',FAILED:'同步失败',OUTDATED:'已过期'}
const metricItems=computed(()=>[{key:'products',label:'产品',path:'/products'},{key:'algorithms',label:'算法',path:'/algorithms'},{key:'capabilities',label:'模型能力',path:'/model-capabilities'},{key:'scenes',label:'场景',path:'/scenes'},{key:'solutions',label:'方案',path:'/solutions'}])
const mappingFields=[{value:'project_name',label:'项目名称'},{value:'customer_name',label:'客户名称'},{value:'sales_name',label:'所属销售'},{value:'project_region',label:'项目地区'},{value:'export_date',label:'导出日期'},{value:'total_price',label:'项目总价'}]
const bomFields=[{value:'lineNo',label:'序号'},{value:'productName',label:'产品名称'},{value:'model',label:'型号'},{value:'quantity',label:'数量'},{value:'unit',label:'单位'},{value:'unitPrice',label:'项目单价'},{value:'subtotal',label:'小计'},{value:'purpose',label:'用途'},{value:'note',label:'备注'}]
const documentCategories=['全部','产品资料','软件资料','算法资料','模型资料','场景资料','方案资料','招投标资料','其他']
const productCategories=['全部','雷达','AI终端','摄像机','AIS','服务器','软件','附件']
const activeTemplateSheet=computed(()=>templateAnalysis.value?.sheets?.find((item:any)=>item.name===templateMapping.sheetName)||null)
const can=(name:string)=>props.permissions.includes(name)
const canOverride=computed(()=>can('KNOWLEDGE_MANAGE')||can('USER_MANAGE'))
const money=(value:any)=>value==null?'—':'¥ '+Number(value).toLocaleString('zh-CN',{maximumFractionDigits:2})
const projectTotal=computed(()=>bom.value.reduce((sum,item)=>sum+Number(item.unitPrice||0)*Number(item.quantity||0),0))
const projectUnits=computed(()=>bom.value.reduce((sum,item)=>sum+Number(item.quantity||0),0))
const filteredProducts=computed(()=>products.value.filter(item=>{const keyword=candidateSearch.value.trim().toLowerCase();const text=`${item.name||''} ${item.modelCode||''} ${item.category||''}`.toLowerCase();const category=candidateCategory.value==='全部'||text.includes(candidateCategory.value.toLowerCase());return category&&(!keyword||text.includes(keyword))}))
const filteredDocuments=computed(()=>rows.value.filter(item=>{const keyword=documentSearch.value.trim().toLowerCase();const matchesKeyword=!keyword||`${item.name||''} ${item.category||''} ${item.version||''}`.toLowerCase().includes(keyword);const matchesCategory=documentCategory.value==='全部'||item.category===documentCategory.value||(documentCategory.value==='招投标资料'&&item.category==='投标资料');const type=fileType(item)==documentType.value||documentType.value==='全部';return matchesKeyword&&matchesCategory&&type}))
const mappedBomCount=computed(()=>Object.values(templateMapping.bomColumnMappings).filter(Boolean).length)
const missingRequiredMappings=computed(()=>{const missing:string[]=[];if(!templateMapping.placeholderMappings.project_name)missing.push('项目名称');if(!templateMapping.placeholderMappings.customer_name)missing.push('客户名称');if(!templateMapping.bomTemplateRow)missing.push('BOM明细行');if(!templateMapping.bomColumnMappings.productName)missing.push('产品名称');if(!templateMapping.bomColumnMappings.quantity)missing.push('数量');return missing})

async function api(url:string,options:any={}){const response=await fetch(url,{...options,headers:{...(options.body instanceof FormData?{}:{'Content-Type':'application/json'}),Authorization:'Bearer '+props.token,...(options.headers||{})}});const data=response.status===204?null:await response.json().catch(()=>null);if(!response.ok)throw Error(data?.detail||'当前操作暂时无法完成，请稍后重试');return data}
async function perform<T>(task:()=>Promise<T>,fallback:string):Promise<T|undefined>{error.value='';try{return await task()}catch(e:any){error.value=e?.message||fallback;ElMessage.error(error.value);return undefined}}
async function load(){loading.value=true;error.value='';try{const name=String(route.name);active.value=null;preview.value=null;validation.value=null;if(name==='home')dashboard.value=await api('/api/dashboard');if(name==='projects')rows.value=await api('/api/projects');if(name==='project-detail'){active.value=await api('/api/projects/'+route.params.id);bom.value=JSON.parse(JSON.stringify(active.value.currentBomVersion?.items||[]));[templates.value,products.value,bomVersions.value]=await Promise.all([api('/api/excel-templates'),api('/api/products'),api('/api/projects/'+route.params.id+'/bom-versions')])}if(name==='bom-rules'){rules.value=await api('/api/bom/rules');products.value=await api('/api/products');scenes.value=await api('/api/scenes')}if(name==='excel-templates')templates.value=await api('/api/excel-templates');if(name==='documents')rows.value=await api('/api/documents');if(name==='ai-config')scenes.value=await api('/api/scenes')}catch(e:any){error.value=e.message}finally{loading.value=false}}
async function ask(){if(!question.value.trim())return;loading.value=true;answer.value=null;await perform(async()=>{answer.value=await api('/api/ai/chat',{method:'POST',body:JSON.stringify({message:question.value})})},'知识问答暂时无法完成，请稍后重试');loading.value=false}
async function parseRequirement(){if(!rawRequirement.value.trim())return ElMessage.warning('请先描述客户项目需求');loading.value=true;const result=await perform(()=>api('/api/ai/config/parse',{method:'POST',body:JSON.stringify({raw_requirement:rawRequirement.value})}),'智能配单暂时无法完成，请稍后重试');if(result){parsed.value=result;step.value=1;ElMessage.success('需求解析完成')}loading.value=false}
async function createAndConfirm(){if(!projectForm.name||!projectForm.customer||!projectForm.scene_id)return ElMessage.warning('请填写项目名称、客户和场景');loading.value=true;await perform(async()=>{const project=await api('/api/projects',{method:'POST',body:JSON.stringify({...projectForm,raw_requirement:rawRequirement.value,requirements:parsed.value.parsedRequirement})});await api('/api/ai/config/confirm',{method:'POST',body:JSON.stringify({project_id:project.id,raw_requirement:rawRequirement.value,ai_parsed_requirement:parsed.value.parsedRequirement,user_adjusted_requirement:parsed.value.parsedRequirement,confirmed_requirement:parsed.value.parsedRequirement})});recommended.value=await api('/api/bom/recommend',{method:'POST',body:JSON.stringify({project_id:project.id})});createdProjectId.value=project.id;step.value=2;ElMessage.success('推荐方案与BOM已生成')},'推荐方案生成失败，请稍后重试');loading.value=false}
async function saveBom(summary='销售人工调整'){const result=await perform(()=>api('/api/projects/'+route.params.id+'/bom-versions',{method:'POST',body:JSON.stringify({items:bom.value,change_summary:summary,source:'MANUAL_EDIT'})}),'BOM保存失败，请稍后重试');if(result){active.value.currentBomVersion=result;bomVersions.value=await api('/api/projects/'+route.params.id+'/bom-versions');ElMessage.success('V'+result.version+' 已创建')}return result}
async function validateBom(reason=''){const result=await perform(()=>api('/api/bom/validate',{method:'POST',body:JSON.stringify({project_id:Number(route.params.id),override_reason:reason||undefined})}),'配置检查暂时无法完成，请稍后重试');if(result){validation.value=result;overrideDialog.value=false;overrideReason.value='';ElMessage.success(result.overridden?'例外确认已记录':'规则校验完成')}return result}
async function makePreview(){if(!selectedTemplate.value)return ElMessage.warning('请选择Excel模板');loading.value=true;const result=await perform(()=>api('/api/projects/'+route.params.id+'/export-preview?template_id='+selectedTemplate.value,{method:'POST'}),'Excel效果预览生成失败，请稍后重试');if(result){preview.value=result;exportTab.value='effect';ElMessage.success('Excel效果预览已生成')}loading.value=false}
async function saveAndPreview(){if(await saveBom('导出前数据调整'))await makePreview()}
async function exportExcel(){if(!selectedTemplate.value)return ElMessage.warning('请选择Excel模板');const result=await perform(()=>api('/api/projects/'+route.params.id+'/export-excel?template_id='+selectedTemplate.value,{method:'POST'}),'Excel生成失败，请稍后重试');if(!result)return;const response=await fetch(result.downloadUrl,{headers:{Authorization:'Bearer '+props.token}});if(!response.ok)return ElMessage.error('Excel下载失败，请稍后重试');const blob=await response.blob(),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=result.fileName;link.click();setTimeout(()=>URL.revokeObjectURL(url),60000);lastExport.value={...result,version:active.value?.currentBomVersion?.version,time:new Date().toLocaleString(),operator:'当前用户'};ElMessage.success('Excel生成成功')}
async function createRule(){const result=await perform(()=>api('/api/bom/rules',{method:'POST',body:JSON.stringify(ruleForm)}),'规则创建失败');if(result){rules.value=await api('/api/bom/rules');Object.assign(ruleForm,{code:'',name:'',rule_type:'REQUIRE',condition:{sceneId:null},action:{productId:null,quantity:1},enabled:true});ElMessage.success('规则版本 V1 已建立')}}
async function uploadTemplate(event:Event){const input=event.target as HTMLInputElement;if(!input.files?.[0])return;const form=new FormData();form.append('file',input.files[0]);form.append('name',input.files[0].name.replace(/\.xlsx$/i,''));const result=await perform(()=>api('/api/excel-templates',{method:'POST',body:form}),'模板上传失败');if(result){templates.value=await api('/api/excel-templates');ElMessage.success('模板已上传')}input.value=''}
async function openTemplateMapping(item:any){mappingTemplate.value=item;templateAnalysis.value=await api('/api/excel-templates/'+item.id+'/analyze',{method:'POST'});const saved=templateAnalysis.value.mapping||{};templateMapping.sheetName=saved.sheetName||templateAnalysis.value.sheetNames[0];templateMapping.placeholderMappings={...(saved.placeholderMappings||{})};templateMapping.bomTemplateRow=saved.bomTemplateRow||1;templateMapping.bomColumnMappings={...(saved.bomColumnMappings||{})};selectedCell.value='';mappingStep.value=1}
function sheetRows(sheet:any):any[][]{if(!sheet)return[];const cellMap=new Map<string,any>((sheet.cells||[]).map((cell:any)=>[cell.coordinate,cell]));const rowCount=Math.min(Math.max(sheet.maxRow||1,12),40),columnCount=Math.min(Math.max(sheet.maxColumn||1,10),26);return Array.from({length:rowCount},(_,row)=>Array.from({length:columnCount},(_,column)=>{const coordinate=columnName(column+1)+(row+1);return cellMap.get(coordinate)||{coordinate,row:row+1,column:column+1,value:''}}))}
function columnName(value:number){let result='';for(let current=value;current;current=Math.floor((current-1)/26))result=String.fromCharCode(65+(current-1)%26)+result;return result}
function chooseCell(cell:any){selectedCell.value=templateMapping.sheetName+'!'+cell.coordinate}
function mapSelectedCell(){if(!selectedCell.value)return ElMessage.warning('请先点击工作表中的单元格');templateMapping.placeholderMappings={...templateMapping.placeholderMappings,[mappingField.value]:selectedCell.value};mappingStep.value=Math.max(mappingStep.value,2);ElMessage.success('单元格映射已设置')}
async function saveTemplateMapping(){if(!mappingTemplate.value)return;if(missingRequiredMappings.value.length)return ElMessage.warning('请补全必需映射：'+missingRequiredMappings.value.join('、'));const result=await perform(()=>api('/api/excel-templates/'+mappingTemplate.value.id+'/mapping',{method:'POST',body:JSON.stringify({sheet_name:templateMapping.sheetName,placeholder_mappings:templateMapping.placeholderMappings,bom_template_row:templateMapping.bomTemplateRow,bom_column_mappings:templateMapping.bomColumnMappings})}),'模板映射保存失败');if(result){mappingStep.value=5;ElMessage.success('模板映射已保存')}}
function selectDocument(event:Event){const input=event.target as HTMLInputElement;if(!input.files?.[0])return;editingDocument.value=null;pendingDocument.value=input.files[0];documentDialog.value=true;input.value=''}
function editDocument(row:any){editingDocument.value=row;pendingDocument.value=null;Object.assign(documentForm,{category:row.category||'产品资料',version:row.version||'V1.0',description:row.description||'',applicable_models:row.applicableModels||'',applicable_versions:row.applicableVersions||'',center_type:row.centerType||'',center_id:row.centerId||null,knowledge_enabled:Boolean(row.knowledgeEnabled)});documentDialog.value=true}
async function uploadDocument(){if(!pendingDocument.value)return;const form=new FormData();form.append('file',pendingDocument.value);Object.entries(documentForm).forEach(([key,value])=>{if(value!==null&&value!=='')form.append(key,String(value))});const result=await perform(()=>api('/api/documents',{method:'POST',body:form}),'资料上传失败，请稍后重试');if(result){rows.value=await api('/api/documents');documentDialog.value=false;pendingDocument.value=null;resetDocumentForm();ElMessage.success('资料已保存为草稿')}}
async function saveDocumentMetadata(){if(!editingDocument.value)return uploadDocument();const result=await perform(()=>api('/api/documents/'+editingDocument.value.id,{method:'PATCH',body:JSON.stringify({category:documentForm.category,version:documentForm.version,description:documentForm.description,applicable_models:documentForm.applicable_models,applicable_versions:documentForm.applicable_versions,center_type:documentForm.center_type||null,center_id:documentForm.center_id,knowledge_enabled:documentForm.knowledge_enabled})}),'资料信息保存失败');if(result){rows.value=await api('/api/documents');documentDialog.value=false;editingDocument.value=null;ElMessage.success('资料信息已保存')}}
async function publishDocument(row:any){await ElMessageBox.confirm(`确认发布“${row.name}”？发布后将作为当前业务资料使用。`,'发布资料',{confirmButtonText:'确认发布',cancelButtonText:'取消',type:'warning'});let passed=false;await perform(async()=>{await api('/api/documents/'+row.id+'/publish',{method:'POST'});if(row.knowledgeEnabled)await api('/api/documents/'+row.id+'/knowledge-sync',{method:'POST'});rows.value=await api('/api/documents');passed=true},'资料发布失败');if(passed)ElMessage.success(row.knowledgeEnabled?'资料发布成功并已同步知识库':'资料发布成功')}
async function openDocument(row:any,download=false){if(download){const response=await fetch('/api/documents/'+row.id+'/download',{headers:{Authorization:'Bearer '+props.token}});if(!response.ok)return ElMessage.error('文件下载失败');const blob=await response.blob(),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=row.originalFileName||row.name;link.click();setTimeout(()=>URL.revokeObjectURL(url),60000);return}previewDocument.value=row;documentPreview.value=true;documentPreviewLoading.value=true;if(documentPreviewUrl.value)URL.revokeObjectURL(documentPreviewUrl.value);const response=await fetch('/api/documents/'+row.id+'/preview',{headers:{Authorization:'Bearer '+props.token}});if(!response.ok){documentPreviewLoading.value=false;return ElMessage.error('在线预览生成失败，可下载原文件查看。')}documentPreviewUrl.value=URL.createObjectURL(await response.blob());documentPreviewLoading.value=false}
function openSource(source:any){if(source.type==='documents')return openDocument(source);if(source.url)return router.push(source.url)}
function resetDocumentForm(){Object.assign(documentForm,{category:'产品资料',version:'V1.0',description:'',applicable_models:'',applicable_versions:'',center_type:'',center_id:null,knowledge_enabled:false})}
function addProductToBom(product:any){bom.value.push({productId:product.id,productName:product.name,model:product.modelCode,quantity:1,unit:'台',unitPrice:product.referencePrice||0,referencePrice:product.referencePrice||0,purpose:'',note:'',manualEdited:true});ElMessage.success(product.name+' 已加入当前BOM')}
function beginBomEdit(row:any,index:number){bomEditIndex.value=index;Object.keys(bomDraft).forEach(key=>delete bomDraft[key]);Object.assign(bomDraft,JSON.parse(JSON.stringify(row)),{_before:JSON.parse(JSON.stringify(row))});bomDrawer.value=true}
function commitBomEdit(){const before=bomDraft._before||{};const changed=['quantity','unitPrice','purpose','note','model'].filter(key=>String(before[key]??'')!==String(bomDraft[key]??''));const next={...bomDraft,manualEdited:true,changedFields:changed};delete next._before;bom.value.splice(bomEditIndex.value,1,next);bomDrawer.value=false;ElMessage.success('BOM行已更新，保存后将创建新版本')}
function removeBom(index:number){ElMessageBox.confirm('确认从当前BOM中删除该产品？','删除BOM项',{type:'warning',confirmButtonText:'确认删除',cancelButtonText:'取消'}).then(()=>bom.value.splice(index,1)).catch(()=>{})}
function moveBom(index:number,delta:number){const target=index+delta;if(target<0||target>=bom.value.length)return;const [item]=bom.value.splice(index,1);bom.value.splice(target,0,item)}
function fileType(item:any){const name=(item.originalFileName||item.name||'').toLowerCase();if(name.endsWith('.pdf'))return'PDF';if(/\.docx?$/.test(name))return'Word';if(/\.xlsx?$/.test(name))return'Excel';if(/\.pptx?$/.test(name))return'PPT';if(/\.(png|jpe?g|gif|webp)$/.test(name))return'图片';return'其他'}
function fileSize(value:any){const size=Number(value||0);if(size<1024)return size+' B';if(size<1024*1024)return(size/1024).toFixed(1)+' KB';return(size/1024/1024).toFixed(1)+' MB'}
function requirementValue(key:string,value:any){if(typeof value==='boolean')return value?'需要':'不需要';if(key==='upstreamKm'||key==='downstreamKm')return value+' km';if(key==='ptzCount')return '球机 × '+value;if(key==='continuousOperation')return value?'7×24小时':'常规运行';return value}
function answerProducts(){return (answer.value?.sources||[]).filter((item:any)=>item.type==='products')}
function answerDocuments(){return (answer.value?.sources||[]).filter((item:any)=>item.type==='documents')}
watch(()=>route.fullPath,load);onMounted(load);onBeforeUnmount(()=>{if(documentPreviewUrl.value)URL.revokeObjectURL(documentPreviewUrl.value)})
</script>

<template>
 <div v-loading="loading" class="phase2"><el-alert v-if="error" :title="error" type="error" show-icon closable @close="error=''"/>
  <template v-if="route.name==='home'"><section class="ai-portal"><div class="ai-heading"><div class="ai-symbol"><el-icon><ChatDotRound/></el-icon></div><div><span>产品知识门户</span><h1>海智 AI 助手</h1><p>可以查询产品、软件、算法、模型、场景、方案和资料，也可以进入智能配单。</p></div></div><div class="ai-composer"><el-input v-model="question" size="large" placeholder="请输入产品知识问题……" @keyup.enter="ask"/><el-button type="primary" size="large" @click="ask">发送</el-button><el-button v-if="can('BOM_EDIT')" class="config-cta" size="large" @click="router.push('/ai-config')">智能配单</el-button></div><div class="quick"><span>你可以问：</span><button v-for="item in ['海智AI分析终端支持哪些算法？','有哪些雷达产品？','桥梁防撞有哪些标准方案？','帮我找AI终端使用说明书。']" :key="item" @click="question=item;ask()">{{item}}</button></div><article v-if="answer" class="ai-answer"><header><div class="answer-avatar">AI</div><div><b>海智 AI</b><small>基于当前有效知识回答</small></div></header><p>{{answer.answer}}</p><div v-if="answerProducts().length" class="answer-section"><h3>相关产品</h3><div class="answer-products"><button v-for="source in answerProducts()" :key="source.id" @click="openSource(source)"><img src="/assets/product-terminal.png" alt="产品图片"/><span><b>{{source.name}}</b><small>查看型号、参数与关联能力</small><em>查看详情 →</em></span></button></div></div><div v-if="answerDocuments().length" class="answer-section"><h3>相关资料</h3><div class="answer-docs"><div v-for="source in answerDocuments()" :key="source.id"><span class="file-badge">资料</span><b>{{source.name}}</b><el-button link type="primary" @click="openSource(source)">在线预览</el-button><el-button v-if="source.canDownload" link @click="openDocument(source,true)">下载</el-button></div></div></div><div v-if="answer.configurationIntent&&can('BOM_EDIT')" class="config-intent"><div><b>这是一个项目配置需求</b><p>建议进入智能配单，系统会携带当前问题继续分析。</p></div><el-button type="primary" @click="router.push({path:'/ai-config',query:{requirement:answer.configurationInput}})">进入智能配单</el-button></div></article></section>
   <section v-if="dashboard" class="dashboard"><div class="metric-grid"><button v-for="item in metricItems" :key="item.key" class="metric" @click="router.push(item.path)"><strong>{{dashboard.metrics[item.key]||0}}</strong><span>{{item.label}}</span></button></div><div class="dashboard-grid"><article class="dashboard-block wide"><div class="block-head"><div><h2>核心产品</h2><p>常用产品与主力型号</p></div><el-button link @click="router.push('/products')">查看全部</el-button></div><div class="product-strip"><button v-for="item in dashboard.coreProducts" :key="item.id" @click="router.push('/products/'+item.id)"><img :src="item.image||'/assets/product-terminal.png'" :alt="item.name"/><span><b>{{item.name}}</b><small>{{item.modelCode}}</small><p>{{item.summary||'查看产品技术参数和适配能力'}}</p><em>查看详情</em></span></button></div></article><article class="dashboard-block"><div class="block-head"><div><h2>常用场景</h2><p>从业务问题快速进入知识</p></div></div><button v-for="item in dashboard.commonScenes" :key="item.id" class="scene-row" @click="router.push('/scenes/'+item.id)"><span class="scene-visual">海智</span><span><b>{{item.name}}</b><small>{{item.category}} · 查看业务说明和标准方案</small></span><em>查看</em></button></article><article v-if="can('BOM_VIEW')" class="dashboard-block"><div class="block-head"><div><h2>最近项目</h2><p>继续未完成的项目配单</p></div><el-button link @click="router.push('/projects')">查看全部</el-button></div><el-empty v-if="!dashboard.recentProjects.length" description="暂无项目配单" :image-size="54"/><button v-for="item in dashboard.recentProjects" :key="item.id" class="list-row" @click="router.push('/projects/'+item.id)"><span><b>{{item.name}}</b><small>{{item.customer}} · {{statusLabels[item.status]}}</small></span><em>V{{item.bomVersion||0}}</em></button></article><article class="dashboard-block"><div class="block-head"><div><h2>最近更新</h2><p>知识内容变更动态</p></div></div><button v-for="item in dashboard.recentUpdates" :key="item.type+item.id" class="list-row" @click="router.push(item.url)"><span><b>{{item.name}}</b><small>{{item.typeLabel}}</small></span><em>查看</em></button></article></div></section></template>

  <template v-else-if="route.name==='ai-config'"><div class="page-head"><div><span class="eyebrow">AI 辅助工作流</span><h1>智能配单</h1><p>用自然语言描述需求，确认后由规则引擎匹配真实产品与标准方案。</p></div></div><el-steps :active="step" finish-status="success" align-center class="flow-steps"><el-step title="需求解析"/><el-step title="确认需求"/><el-step title="推荐方案 / BOM"/></el-steps><section v-if="step===0" class="requirement-entry"><div class="entry-copy"><span>STEP 1</span><h2>描述客户项目需求</h2><p>直接用自然语言描述场景、范围、设备、能力和运行要求即可。</p></div><el-input v-model="rawRequirement" type="textarea" :rows="9" placeholder="例如：某桥梁上下游各3公里，需要4个球机，支持AIS融合、船名OCR、偏航预警，7×24小时运行。"/><div class="entry-actions"><small>系统将识别场景、关键条件和能力要求</small><el-button type="primary" size="large" @click="parseRequirement">开始智能分析</el-button></div><div class="example-line"><b>常用示例</b><button @click="rawRequirement='某桥梁上下游各3公里，需要4个球机，支持AIS融合、船名OCR、偏航预警，7×24小时运行。'">桥梁防撞标准需求</button></div></section><section v-if="step===1&&parsed" class="analysis-workspace"><div class="analysis-original"><span>原始需求</span><p>{{parsed.rawRequirement}}</p></div><div class="section-title"><div><span>AI 识别结果</span><h2>已提取的项目条件</h2></div><el-tag type="success">解析完成</el-tag></div><div class="requirement-cards"><article v-for="(value,key) in parsed.parsedRequirement" :key="key"><span>{{requirementLabels[String(key)]||'补充需求'}}</span><b>{{requirementValue(String(key),value)}}</b></article></div><div v-if="parsed.missingFields?.length" class="confirm-needed"><h3>需要你确认</h3><div v-for="item in parsed.missingFields" :key="item.field" class="question-card"><b>{{item.question}}</b><div><el-button>已有</el-button><el-button>没有</el-button><el-button>不确定</el-button></div></div></div><el-alert v-else title="需求信息完整，可以进入方案推荐。" type="success" show-icon :closable="false"/><div class="project-fields"><h3>建立项目档案</h3><div class="form-grid"><el-input v-model="projectForm.name" placeholder="项目名称"/><el-input v-model="projectForm.customer" placeholder="客户名称"/><el-input v-model="projectForm.region" placeholder="项目地区"/><el-select v-model="projectForm.scene_id" placeholder="业务场景"><el-option v-for="scene in scenes" :key="scene.id" :label="scene.name" :value="scene.id"/></el-select></div></div><div class="step-actions"><el-button @click="step=0">返回修改</el-button><el-button type="primary" :icon="Check" @click="createAndConfirm">确认需求</el-button></div></section><section v-if="step===2&&recommended" class="recommendation"><div class="recommend-hero"><span class="recommend-mark"><el-icon><Check/></el-icon></span><div><span>推荐方案摘要</span><h2>桥梁防撞标准方案</h2><p>基于已确认需求、当前有效标准方案和BOM规则生成。</p></div><el-tag type="success">推荐完成</el-tag></div><div class="recommend-grid"><div><span>适用场景</span><b>{{parsed?.parsedRequirement?.scene||'桥梁防撞'}}</b></div><div><span>关键产品</span><b>{{recommended.items?.length||0}} 类</b></div><div><span>设备数量</span><b>{{recommended.items?.reduce((sum:number,item:any)=>sum+Number(item.quantity||0),0)||0}}</b></div><div><span>当前版本</span><b>V{{recommended.version}}</b></div></div><div class="coverage"><b>能力覆盖</b><span>AIS融合 ✓</span><span>船名OCR ✓</span><span>偏航预警 ✓</span><span>视频监控 ✓</span></div><div class="recommend-reason"><b>推荐原因</b><p>标准方案覆盖当前需求识别出的核心能力，产品与型号均来自产品中心，进入项目后可继续人工调整并执行规则校验。</p></div><div class="step-actions"><el-button @click="step=1">返回确认</el-button><el-button type="primary" size="large" @click="router.push('/projects/'+createdProjectId)">进入 BOM 配置</el-button></div></section></template>

  <template v-else-if="route.name==='projects'"><div class="page-head"><div><h1>项目配单</h1><p>管理项目需求、BOM版本、规则校验和Excel导出。</p></div><el-button type="primary" @click="router.push('/ai-config')">新建智能配单</el-button></div><el-empty v-if="!rows.length" description="暂无项目配单"><el-button type="primary" @click="router.push('/ai-config')">开始智能配单</el-button></el-empty><el-table v-else :data="rows" class="business-table" @row-click="(row:any)=>router.push('/projects/'+row.id)"><el-table-column prop="name" label="项目名称" min-width="220"/><el-table-column prop="customer" label="客户"/><el-table-column prop="region" label="地区"/><el-table-column prop="scene" label="场景"/><el-table-column label="状态"><template #default="scope"><el-tag>{{statusLabels[scope.row.status]}}</el-tag></template></el-table-column><el-table-column prop="bomVersion" label="当前BOM版本"/></el-table></template>

  <template v-else-if="route.name==='project-detail'&&active"><section class="project-hero"><div><el-button link @click="router.push('/projects')">← 返回项目列表</el-button><span class="eyebrow">项目配单</span><h1>{{active.name}}</h1><p>{{active.customer}} · {{active.region}} · {{active.scene}}</p></div><div class="project-kpis"><div><span>项目状态</span><b>{{statusLabels[active.status]}}</b></div><div v-if="can('PRICE_VIEW')"><span>项目参考总价</span><b>{{money(projectTotal)}}</b></div><div><span>当前BOM</span><b>V{{active.currentBomVersion?.version||0}}</b></div></div></section><div class="lifecycle"><div v-for="(item,index) in ['需求整理','配单中','已确认','已导出','已归档']" :key="item" :class="{active:index===Object.keys(statusLabels).indexOf(active.status),done:index<Object.keys(statusLabels).indexOf(active.status)}"><span>{{index+1}}</span><b>{{item}}</b></div></div><el-tabs v-model="projectTab" class="project-tabs"><el-tab-pane label="项目概览" name="overview"><div class="overview-grid"><section class="info-card"><h3>项目基本信息</h3><dl><div><dt>客户</dt><dd>{{active.customer}}</dd></div><div><dt>项目地区</dt><dd>{{active.region||'未填写'}}</dd></div><div><dt>业务场景</dt><dd>{{active.scene}}</dd></div><div><dt>当前状态</dt><dd>{{statusLabels[active.status]}}</dd></div><div><dt>更新时间</dt><dd>{{active.updatedAt}}</dd></div></dl></section><section class="info-card"><h3>当前BOM摘要</h3><div class="summary-metrics"><div><strong>{{bom.length}}</strong><span>设备种类</span></div><div><strong>{{projectUnits}}</strong><span>设备总数</span></div><div v-if="can('PRICE_VIEW')"><strong>{{money(projectTotal)}}</strong><span>项目参考总价</span></div></div><p>{{active.currentBomVersion?.changeSummary||'尚未建立BOM版本'}}</p><el-button type="primary" @click="projectTab='bom'">进入BOM配置</el-button></section><section class="info-card wide"><h3>需求摘要</h3><p>{{active.notes||'需求已经通过智能配单确认，详细条件可在需求信息中查看。'}}</p></section></div></el-tab-pane><el-tab-pane label="需求信息" name="requirements"><section class="info-card"><h3>已确认需求</h3><p>{{active.notes||'当前项目需求已确认，推荐BOM依据项目场景与当前有效规则生成。'}}</p><div class="coverage"><span>{{active.scene}} ✓</span><span>真实产品匹配 ✓</span><span>规则校验可用 ✓</span></div></section></el-tab-pane>
    <el-tab-pane label="BOM配置" name="bom"><div class="bom-layout" :class="{leftCollapsed,rightCollapsed}"><aside class="candidate"><header><div><h3>候选产品</h3><p>从产品中心添加真实产品</p></div><el-button text @click="leftCollapsed=!leftCollapsed">{{leftCollapsed?'展开':'收起'}}</el-button></header><template v-if="!leftCollapsed"><el-input v-model="candidateSearch" :prefix-icon="Search" placeholder="搜索产品或型号" clearable/><div class="category-tabs"><button v-for="item in productCategories" :key="item" :class="{active:candidateCategory===item}" @click="candidateCategory=item">{{item}}</button></div><div class="candidate-list"><article v-for="item in filteredProducts" :key="item.id"><img :src="item.image||'/assets/product-terminal.png'" :alt="item.name"/><div><b>{{item.name}}</b><small>{{item.modelCode}}</small><span v-if="can('PRICE_VIEW')">{{money(item.referencePrice)}}</span></div><el-button link type="primary" @click="addProductToBom(item)">添加</el-button></article><el-empty v-if="!filteredProducts.length" description="未找到匹配产品" :image-size="50"/></div></template></aside><section class="bom-table"><div class="section-actions"><div><h3>当前 BOM · V{{active.currentBomVersion?.version||0}}</h3><p>默认展示，点击编辑后修改；保存将创建不可变新版本。</p></div><el-button type="primary" @click="saveBom()">保存新版本</el-button></div><el-table :data="bom" border class="business-table"><el-table-column label="产品 / 型号" min-width="190"><template #default="s"><div class="product-cell"><b>{{s.row.productName}}</b><small>{{s.row.model}}</small></div></template></el-table-column><el-table-column prop="quantity" label="数量" width="72"/><el-table-column prop="unit" label="单位" width="66"/><el-table-column v-if="can('PRICE_VIEW')" label="项目单价" width="120"><template #default="s">{{money(s.row.unitPrice)}}</template></el-table-column><el-table-column v-if="can('PRICE_VIEW')" label="小计" width="130"><template #default="s">{{money(Number(s.row.unitPrice||0)*Number(s.row.quantity||0))}}</template></el-table-column><el-table-column prop="purpose" label="用途" min-width="120"/><el-table-column label="状态" width="90"><template #default="s"><el-tooltip v-if="s.row.manualEdited" placement="top"><template #content><div>人工调整字段：{{(s.row.changedFields||['数量/价格/用途/备注']).join('、')}}</div></template><el-tag type="warning">人工调整</el-tag></el-tooltip><el-tag v-else type="success">规则推荐</el-tag></template></el-table-column><el-table-column label="操作" width="176" fixed="right"><template #default="s"><el-button link @click="beginBomEdit(s.row,s.$index)">编辑</el-button><el-button link @click="moveBom(s.$index,-1)" :disabled="s.$index===0">上移</el-button><el-button link @click="moveBom(s.$index,1)" :disabled="s.$index===bom.length-1">下移</el-button><el-button link type="danger" @click="removeBom(s.$index)">删除</el-button></template></el-table-column></el-table><div class="bom-footer"><span>共 {{bom.length}} 类，{{projectUnits}} 件</span><strong v-if="can('PRICE_VIEW')">合计 {{money(projectTotal)}}</strong></div><div class="coverage"><b>能力覆盖</b><span>AIS融合 ✓</span><span>船名OCR ✓</span><span>偏航预警 ✓</span><span>视频监控 ✓</span></div></section><aside class="validation"><header><div><h3>配置检查</h3><p>规则与兼容性校验</p></div><el-button text @click="rightCollapsed=!rightCollapsed">{{rightCollapsed?'展开':'收起'}}</el-button></header><template v-if="!rightCollapsed"><el-button type="primary" :icon="Refresh" @click="validateBom()">重新校验</el-button><div v-if="validation" class="validation-summary" :class="validation.status.toLowerCase()"><b>{{validation.status==='PASS'?'✓':validation.status==='WARNING'?'⚠':'✕'}} {{validationLabels[validation.status]}}</b><span>通过 {{validation.passCount}} · 提醒 {{validation.warningCount}} · 错误 {{validation.errorCount}}</span></div><div v-if="validation" class="validation-results"><article v-for="(item,index) in validation.results" :key="index" :class="item.level.toLowerCase()"><el-tag :type="item.level==='ERROR'?'danger':item.level==='WARNING'?'warning':'success'">{{item.level}}</el-tag><div><b>{{item.ruleId?'业务规则':'产品有效性检查'}}</b><p>{{item.message}}</p><small>{{item.level==='ERROR'?'请修正BOM后重新校验':'当前配置无需处理'}}</small></div></article></div><el-empty v-else description="尚未执行配置检查" :image-size="56"/><div v-if="validation?.status==='ERROR'" class="override-box"><p v-if="!canOverride">请联系产品经理或管理员处理。</p><el-button v-else type="warning" @click="overrideDialog=true">例外确认</el-button></div></template></aside></div></el-tab-pane>
    <el-tab-pane label="版本历史" name="history"><section class="history-list"><article v-for="(item,index) in bomVersions" :key="item.id" :class="{current:index===0}"><span>V{{item.version}}</span><div><b>{{item.changeSummary}}</b><p>{{item.source==='AI_RECOMMEND'?'AI首次推荐':'人工调整'}} · {{item.createdAt}}</p></div><el-tag v-if="index===0" type="success">当前版本</el-tag><el-button link @click="bom=JSON.parse(JSON.stringify(item.items));projectTab='bom'">{{index===0?'查看':'复制为新版本'}}</el-button></article></section></el-tab-pane>
    <el-tab-pane label="Excel导出" name="export"><div class="export-notice"><b>导出前最终调整</b><p>这里的修改会创建新的BOM版本，不会覆盖历史版本或产品中心参考价格。</p></div><div class="export-tools"><el-select v-model="selectedTemplate" placeholder="选择Excel模板"><el-option v-for="item in templates" :key="item.id" :label="item.name+' · V'+item.currentVersion" :value="item.id"/></el-select><el-button @click="makePreview">生成效果预览</el-button><el-button type="primary" :icon="Download" :disabled="!preview" @click="exportExcel">生成Excel</el-button></div><el-tabs v-model="exportTab"><el-tab-pane label="数据调整" name="data"><el-table :data="bom" border class="business-table"><el-table-column label="产品" min-width="180"><template #default="s"><b>{{s.row.productName}}</b></template></el-table-column><el-table-column prop="model" label="型号" min-width="130"/><el-table-column prop="quantity" label="数量" width="80"/><el-table-column prop="unit" label="单位" width="70"/><el-table-column v-if="can('PRICE_VIEW')" label="项目单价" width="130"><template #default="s">{{money(s.row.unitPrice)}}</template></el-table-column><el-table-column prop="purpose" label="用途" min-width="140"/><el-table-column prop="note" label="备注" min-width="140"/><el-table-column label="操作" width="120"><template #default="s"><el-button link @click="beginBomEdit(s.row,s.$index)">编辑</el-button><el-button link type="danger" @click="removeBom(s.$index)">删除</el-button></template></el-table-column></el-table><div class="export-save"><el-button :icon="Plus" @click="projectTab='bom'">添加产品</el-button><el-button type="primary" @click="saveAndPreview">保存新版本并预览</el-button></div></el-tab-pane><el-tab-pane label="Excel效果预览" name="effect"><div class="preview-toolbar"><div><el-button @click="exportTab='data'">返回数据调整</el-button><span v-if="preview">{{preview.template.name}} · V{{preview.template.version}} · {{preview.template.sheetName}}</span></div><el-button-group><el-button @click="sheetZoom=75">75%</el-button><el-button @click="sheetZoom=100">100%</el-button><el-button @click="sheetZoom=125">125%</el-button><el-button @click="sheetZoom=90">适应宽度</el-button></el-button-group></div><el-empty v-if="!preview" description="请选择模板并生成Excel效果预览"/><div v-else class="excel-preview-shell"><iframe class="excel-effect" :style="{width:sheetZoom+'%'}" :srcdoc="preview.html" title="Excel效果预览" sandbox=""/></div><div v-if="lastExport" class="export-result"><el-icon><Check/></el-icon><div><b>Excel生成成功</b><p>{{lastExport.fileName}} · BOM V{{lastExport.version}} · {{lastExport.time}}</p></div><el-button type="primary" @click="exportExcel">重新下载</el-button></div></el-tab-pane></el-tabs></el-tab-pane><el-tab-pane label="操作记录" name="audit"><el-empty description="操作记录由审计日志统一留存"/></el-tab-pane></el-tabs></template>

  <template v-else-if="route.name==='bom-rules'"><div class="page-head"><div><h1>BOM规则</h1><p>使用业务条件维护规则，每次修改自动保留版本。</p></div></div><section class="work-card"><div class="rule-grid"><el-input v-model="ruleForm.code" placeholder="规则编码"/><el-input v-model="ruleForm.name" placeholder="规则名称"/><el-select v-model="ruleForm.rule_type"><el-option v-for="item in Object.keys(ruleTypeLabels)" :key="item" :label="ruleTypeLabels[item]" :value="item"/></el-select><el-select v-model="ruleForm.condition.sceneId" placeholder="适用场景"><el-option v-for="item in scenes" :key="item.id" :label="item.name" :value="item.id"/></el-select><el-select v-model="ruleForm.action.productId" placeholder="规则关联产品"><el-option v-for="item in products" :key="item.id" :label="item.name" :value="item.id"/></el-select><el-input-number v-model="ruleForm.action.quantity" :min="1"/><el-button type="primary" @click="createRule">创建规则</el-button></div></section><el-table :data="rules" class="business-table"><el-table-column prop="code" label="编码"/><el-table-column prop="name" label="名称"/><el-table-column label="类型"><template #default="s">{{ruleTypeLabels[s.row.ruleType]||'业务规则'}}</template></el-table-column><el-table-column prop="version" label="版本"/><el-table-column label="状态"><template #default="s"><el-tag :type="s.row.enabled?'success':'info'">{{s.row.enabled?'启用':'停用'}}</el-tag></template></el-table-column></el-table></template>

  <template v-else-if="route.name==='excel-templates'"><div class="page-head"><div><h1>Excel模板</h1><p>按步骤完成工作表、项目字段和BOM明细映射，保留公司原始Excel样式。</p></div><label class="upload-button"><el-icon><Upload/></el-icon>上传模板<input type="file" accept=".xlsx" @change="uploadTemplate"/></label></div><el-steps :active="mappingStep" class="template-steps" finish-status="success"><el-step title="上传模板"/><el-step title="选择Sheet"/><el-step title="映射项目字段"/><el-step title="设置BOM行"/><el-step title="映射BOM列"/><el-step title="预览并保存"/></el-steps><el-table :data="templates" class="business-table"><el-table-column prop="name" label="模板名称"/><el-table-column prop="description" label="说明"/><el-table-column prop="currentVersion" label="当前版本"/><el-table-column prop="updatedAt" label="更新时间"/><el-table-column label="操作" width="130"><template #default="s"><el-button link type="primary" @click="openTemplateMapping(s.row)">配置映射</el-button></template></el-table-column></el-table><section v-if="mappingTemplate&&templateAnalysis" class="mapping-workspace"><div class="section-actions"><div><h2>{{mappingTemplate.name}} · 可视化字段映射</h2><p>点击工作表单元格，在右侧选择业务字段；用户无需查看或编辑JSON。</p></div><el-button type="primary" @click="saveTemplateMapping">预览并保存</el-button></div><div class="sheet-toolbar"><el-select v-model="templateMapping.sheetName" placeholder="选择工作表"><el-option v-for="name in templateAnalysis.sheetNames" :key="name" :label="name" :value="name"/></el-select><el-button-group><el-button @click="sheetZoom=75">75%</el-button><el-button @click="sheetZoom=100">100%</el-button><el-button @click="sheetZoom=125">125%</el-button><el-button @click="sheetZoom=90">适应宽度</el-button></el-button-group></div><div class="mapping-main"><div class="cell-sheet"><table v-if="activeTemplateSheet" :style="{zoom:sheetZoom/100}"><thead><tr><th></th><th v-for="cell in sheetRows(activeTemplateSheet)[0]" :key="cell.column">{{columnName(cell.column)}}</th></tr></thead><tbody><tr v-for="row in sheetRows(activeTemplateSheet)" :key="row[0].row"><th>{{row[0].row}}</th><td v-for="cell in row" :key="cell.coordinate" :class="{selected:selectedCell===templateMapping.sheetName+'!'+cell.coordinate,mapped:Object.values(templateMapping.placeholderMappings).includes(templateMapping.sheetName+'!'+cell.coordinate)}" @click="chooseCell(cell)">{{cell.value}}</td></tr></tbody></table></div><aside class="mapping-panel"><span>映射字段</span><h3>当前选择：{{selectedCell||'未选择单元格'}}</h3><el-select v-model="mappingField"><el-option v-for="field in mappingFields" :key="field.value" :label="field.label" :value="field.value"/></el-select><el-button type="primary" :disabled="!selectedCell" @click="mapSelectedCell">保存当前映射</el-button><div class="mapped-fields"><el-tag v-for="field in mappingFields" :key="field.value" :type="templateMapping.placeholderMappings[field.value]?'success':'info'">{{field.label}}：{{templateMapping.placeholderMappings[field.value]||'未映射'}}</el-tag></div></aside></div><div class="bom-mapping"><div><span>STEP 4</span><h3>BOM明细模板行</h3><p>选择模板中用于重复写入BOM明细的起始行。</p><el-input-number v-model="templateMapping.bomTemplateRow" :min="1"/></div><div><div class="mapping-progress"><h3>BOM列映射完成：{{mappedBomCount}} / {{bomFields.length}}</h3><span v-if="mappedBomCount<bomFields.length">缺失：{{bomFields.filter(field=>!templateMapping.bomColumnMappings[field.value]).map(field=>field.label).join('、')}}</span><el-tag v-else type="success">映射完整</el-tag></div><div class="bom-map-grid"><label v-for="field in bomFields" :key="field.value"><span>{{field.label}}</span><el-input v-model="templateMapping.bomColumnMappings[field.value]" placeholder="例如 A"/></label></div></div></div><el-alert v-if="missingRequiredMappings.length" :title="'保存前请补全：'+missingRequiredMappings.join('、')" type="warning" :closable="false" show-icon/></section></template>

  <template v-else-if="route.name==='documents'"><div class="page-head"><div><h1>资料中心</h1><p>统一管理产品、软件、算法、模型、场景和方案资料。</p></div><label v-if="can('DOCUMENT_EDIT')" class="upload-button"><el-icon><Upload/></el-icon>上传资料<input type="file" accept=".pdf,.png,.jpg,.doc,.docx,.xls,.xlsx,.ppt,.pptx,.txt" @change="selectDocument"/></label></div><section class="document-toolbar"><el-input v-model="documentSearch" :prefix-icon="Search" placeholder="搜索文件名称、版本或分类" clearable/><el-select v-model="documentCategory"><el-option v-for="item in documentCategories" :key="item" :label="item" :value="item"/></el-select><el-select v-model="documentType"><el-option v-for="item in ['全部','PDF','Word','Excel','PPT','图片','其他']" :key="item" :label="item==='全部'?'全部文件类型':item" :value="item"/></el-select></section><el-empty v-if="!filteredDocuments.length" description="暂无资料"><p>上传产品手册、软件说明、方案文件等资料，统一进行在线预览和知识管理。</p></el-empty><div v-else class="document-list"><article v-for="item in filteredDocuments" :key="item.id"><span class="document-icon">{{fileType(item)}}</span><div class="document-main"><b>{{item.name}}</b><p>{{item.category}} · 关联 {{item.centerType||'通用资料'}} {{item.centerId||''}}</p><small>{{fileSize(item.fileSize)}} · {{item.updatedAt}}</small></div><div class="document-tags"><el-tag>{{item.version}}</el-tag><el-tag :type="item.status==='PUBLISHED'?'success':'info'">{{documentStatusLabels[item.status]}}</el-tag><el-tag :type="item.documentStatus==='CURRENT'?'success':'info'">{{documentStatusLabels[item.documentStatus]}}</el-tag><el-tag :type="item.knowledgeStatus==='SYNCED'?'success':item.knowledgeStatus==='FAILED'?'danger':'warning'">{{documentStatusLabels[item.knowledgeStatus]||'未启用'}}</el-tag></div><div class="document-actions"><el-button v-if="item.canPreview" link type="primary" @click="openDocument(item)">预览</el-button><el-button v-if="item.canDownload" link @click="openDocument(item,true)">下载</el-button><el-dropdown v-if="can('DOCUMENT_EDIT')"><el-button link>更多</el-button><template